mapper.update:

/* regDsDataSellerMpDsOrderObtnodrReceiptPop_1 */
	UPDATE DB_OFF_IV A	
	   SET A.DS_DATE=TO_DATE(#{st_ds_date},'YYYYMMDDHH24MISS'),	
	       A.REASON_REMARK=#{st_reason_remark}	
	 WHERE A.BUYER=#{st_buyer}	
	   AND A.ADD_DATE=#{st_add_date}	
	   AND A.SEQ=${st_seq}		
	   AND A.DS_SEQ=${st_ds_seq}


/* regDsDataSellerMpDsOrderObtnodrReceiptPop_2 */
	UPDATE DB_OFF_PO A	
	   SET A.DO_QTY=NVL(A.DO_QTY,0)+${st_ds_qty}	
	 WHERE A.BUYER=#{st_buyer}	
	   AND A.ADD_DATE=#{st_add_date}	
	   AND A.SEQ=${st_seq}
